import os, re

ROOT = os.path.dirname(os.path.abspath(__file__))
def read(p): return open(os.path.join(ROOT, p), encoding="utf-8").read()
def write(p, t): open(os.path.join(ROOT, p), "w", encoding="utf-8").write(t)

