# 1) تواريخ داخل المقال + إزالة رموز الميتا
for fn in sorted(os.listdir(os.path.join(ROOT, "posts"))):
    if not fn.endswith(".html"): continue
    p = os.path.join("posts", fn)
    t = read(p)
    t = re.sub(r'📅 (\d{4}-\d{2}-\d{2})', r'نُشر: \1', t)
    t = re.sub(r'⏱️ (\d+) دقائق قراءة', r'مدة القراءة: \1 دقائق', t)
    t = re.sub(r'✍️ (فريق تحرير دليلك)', r'الكاتب: \1', t)
    t = re.sub(r'🔄 (آخر تحديث: [^<]+)', r'\1', t)
    t = t.replace('🗂️ ', '')
    # إدراج التوسيع قبل قسم المشاركة
    slug = fn[:-5]
    if slug in EXTRA:
        t = t.replace('<div class="share"', EXTRA[slug] + '\n<div class="share"', 1)
    write(p, t)
print("تم توسيع المقالات + ضبط التواريخ في:", len([s for s in EXTRA if os.path.exists(os.path.join(ROOT,'posts',s+'.html'))]), "مقالًا")

# 2) تقليل الرموز التعبيرية في كل الصفحات
for dp, _, fns in os.walk(ROOT):
    if any(s in dp for s in [".git"]): continue
    for fn in fns:
        if not fn.endswith(".html"): continue
        p = os.path.join(dp, fn)
        t = read(p)
        orig = t
        t = t.replace('✅ ', '')
        t = t.replace('⭐ ', '')
        t = t.replace('📧 ', '')
        t = t.replace(' ❤️', '')
        t = t.replace('📡 ', '')
        t = t.replace('<span class="t-ic">💡</span>', '')
        if t != orig: write(p, t)
print("تم تقليل الرموز التعبيرية.")

